                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    class TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self.cache = {}
            self.expiration_times = {}

        def __getitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            if self.timer() - self.expiration_times[key] > self.ttl:
                del self.cache[key]
                del self.expiration_times[key]
                raise KeyError(key)
            return self.cache[key]

        def __setitem__(self, key, value):
            if self.typed:
                key = (type(key), key)
            self.cache[key] = value
            self.expiration_times[key] = self.timer()
            if len(self.cache) > self.maxsize:
                oldest_key = min(self.expiration_times, key=self.expiration_times.get)
                del self.cache[oldest_key]
                del self.expiration_times[oldest_key]

        def __len__(self):
            return len(self.cache)

    def decorator(func):
        cache = TTLCache(maxsize, ttl, timer, typed)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return cache[(args, tuple(sorted(kwargs.items())))]
            except KeyError:
                result = func(*args, **kwargs)
                cache[(args, tuple(sorted(kwargs.items())))] = result
                return result

        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        if maxsize <= 0:
            return func

        cache = []

        def wrapper(*args, **kwargs):
            key = args + tuple(kwargs.items())
            for entry in cache:
                if entry[0] == key:
                    cache.remove(entry)
                    cache.append(entry)
                    return entry[1]
            result = func(*args, **kwargs)
            cache.append((key, result))
            if len(cache) > maxsize:
                cache.pop(0)
            return result

        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        keys = []
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if typed else (args, tuple(kwargs.items()))
            if key in cache:
                keys.remove(key)
                keys.append(key)
            else:
                if len(cache) >= maxsize:
                    oldest_key = keys.pop(0)
                    del cache[oldest_key]
                keys.append(key)
            cache[key] = func(*args, **kwargs)
            return cache[key]
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    def decorator(func):
        from collections import OrderedDict
        import sys

        class Node:
            def __init__(self, key, value, count=1):
                self.key = key
                self.value = value
                self.count = count

        class LFUCache:
            def __init__(self, capacity):
                self.capacity = capacity
                self.cache = OrderedDict()
                self.counts = {}
                self.min_count = 0

            def get(self, key):
                if key not in self.cache:
                    return -1
                node = self.cache[key]
                del self.cache[key]
                self.cache[key] = self.incr_count(node)
                return node.value

            def put(self, key, value):
                if key in self.cache:
                    self.cache[key] = self.incr_count(self.cache[key], value)
                else:
                    if len(self.cache) >= self.capacity:
                        k, v = self.cache.popitem(last=False)
                        del self.counts[v.count]
                    node = Node(key, value)
                    self.cache[key] = node
                    self.counts[1] = self.cache
                    self.min_count = 1

            def incr_count(self, node, value=None):
                node.count += 1
                if node.count not in self.counts:
                    self.counts[node.count] = OrderedDict()
                if node.key in self.counts[node.count - 1]:
                    del self.counts[node.count - 1][node.key]
                if not self.counts[node.count - 1]:
                    if node.count - 1 == self.min_count:
                        self.min_count += 1
                    del self.counts[node.count - 1]
                if value is not None:
                    node.value = value
                self.counts[node.count][node.key] = node
                return node

        cache = LFUCache(maxsize)
        if typed:
            cache_key = lambda *args, **kwargs: (func.__qualname__, args, tuple(sorted(kwargs.items())) if kwargs else ())
        else:
            cache_key = lambda *args, **kwargs: (func.__qualname__, args, tuple(sorted(kwargs.items())) if kwargs else ())

        def wrapper(*args, **kwargs):
            k = cache_key(*args, **kwargs)
            try:
                return cache.get(k)
            except KeyError:
                pass  # key not found
            v = func(*args, **kwargs)
            cache.put(k, v)
            return v

        return _update_wrapper(wrapper, func)

    return decorator

