def _mergeOrderings(orderings):
    merged = []
    visited = set()
    for ordering in orderings:
        for item in ordering:
            if item not in visited:
                visited.add(item)
                i = len(merged)
                while i > 0 and merged[i - 1] > item:
                    i -= 1
                merged.insert(i, item)
    return merged

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    for cls in classes:
        bases = cls.__bases__
        if len(bases) == 0:
            continue
        for base in bases:
            classes.remove(base)
            minimalBases(classes)
            classes.append(base)
    return classes

