def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing_digests = [digest for digest in digests_used if digest not in self._digests]
    used_but_not_in_manifest = [digest for digest in self._digests if digest not in digests_used]

    if missing_digests:
        raise ValueError(f"Missing digests: {missing_digests}")
    if used_but_not_in_manifest:
        raise ValueError(f"Used but not in manifest: {used_but_not_in_manifest}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, type(self)):
        raise TypeError('prior must be an instance of the same class')

    if self.inventory != prior.inventory:
        raise ValueError('prior inventory must be the same as the current inventory')

    if self.version >= prior.version:
        raise ValueError('prior version must be less than the current version')

    if not self.is_compatible_with(prior):
        raise ValueError('prior is not compatible with the current inventory')

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}
    for logical_path, files in inventory[version].items():
        logical_path_map[logical_path] = set(files)
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity or not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a non-empty dictionary")

    referenced_files = set(fixity.get('files', {}).keys())

    if referencing_files := referenced_files.intersection(manifest_files):
        raise ValueError(f"Referencing files not found in manifest: {', '.join(referencing_files)}")

    if unknown_files := manifest_files - referenced_files:
        raise ValueError(f"Unknown files in manifest: {', '.join(unknown_files)}")

def files_list(path):
    """
    Return the files in `path`
    """
    if os.path.isfile(path):
        return [path]
    elif os.path.isdir(path):
        return [os.path.join(path, f) for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    else:
        raise FileNotFoundError(f"Path {path} does not exist")

