                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    merged = {}
    for key, value in nodes:
        if key.value in merged:
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(merged[key.value], ruamel.yaml.nodes.MappingNode):
                # Recursively deep merge MappingNodes
                merged[key.value].value = deep_merge_nodes(list(zip(key.value, merged[key.value].value + value.value)))
            else:
                # If there is a collision, keep the last value
                merged[key.value] = value
        else:
            merged[key.value] = value
    return list(merged.items())

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size_value = float(size[:-1])
    size_unit = size[-1:].upper()
    if size_unit == 'K':
        return int(size_value * 1024)
    elif size_unit == 'M':
        return int(size_value * 1024 * 1024)
    elif size_unit == 'G':
        return int(size_value * 1024 * 1024 * 1024)
    elif size_unit == 'T':
        return int(size_value * 1024 * 1024 * 1024 * 1024)
    elif size_unit == 'P':
        return int(size_value * 1024 * 1024 * 1024 * 1024 * 1024)
    elif size_unit == 'E':
        return int(size_value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024)
    elif size_unit == 'Z':
        return int(size_value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024)
    elif size_unit == 'Y':
        return int(size_value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024)
    else:
        return int(size_value)

