def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    def passesAllAssertions(candidate, assertions):
        """
        Assert this candidate satisfies an iterable of *assertions*. Assertions
        can be either callables or classes. If the assertions are callables, they
        should take (iface, candidate) as arguments and return True or False.
        If the assertions are classes, an instance of the class is created and
        the constructor is called with (iface, candidate). If an assertion returns
        False, the entire check fails.
        """
        for a in assertions:
            if callable(a):
                if not a(iface, candidate):
                    return False
            else:
                if not a(iface, candidate):
                    return False
        return True

    return passesAllAssertions(candidate, iface._implements)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    for base in bases:
        if hasattr(base, '__class__'):
            base_meta = getattr(base, '__class__')
            if base_meta and issubclass(base_meta, type):
                return base_meta

    return type

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key not in self:
            if default is not __marker:
                return default
            raise KeyError(key)
        return self._dict.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._cache:
        raise KeyError('cache is empty')
    key, value = self._cache.popitem(last=False)
    self._lfu[key].remove(value)
    if not self._lfu[key]:
        del self._lfu[key]
    self._size -= 1
    return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        key, value = self._cache.popitem(last=False)
        self._discard(key)
        return key, value
    except KeyError:
        raise KeyError('cache is empty')

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key = self._recents[-1]
        value = self.data[key]
        self._recents.remove(key)
        del self.data[key]
        return (key, value)
    except IndexError:
        raise KeyError('dictionary is empty')

