def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_dirs = parser_dict.pop('include_dirs', [])
    for include_dir in include_dirs:
        include_file = os.path.join(include_dir, 'parser_dict.yaml')
        if os.path.exists(include_file):
            with open(include_file, 'r') as f:
                included_dict = yaml.safe_load(f)
                parser_dict.update(included_dict)
                self._include_groups(included_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.args:
        if arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]
        elif hasattr(arg, 'default'):
            defaults[arg.name] = arg.default
    return defaults

