def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    required_args = getattr(self, '_required_args', [])
    for arg_name in required_args:
        if arg_name not in args:
            raise ValueError(f"Missing required argument: {arg_name}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for argn, argattrs in args.items():
        if 'length' in argattrs:
            if len(argattrs) > argattrs['length']:
                raise ValueError(f"Argument '{argn}' exceeds specified length")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if not (self.min_value <= arg <= self.max_value):
            raise ValueError(f"Argument {arg} is not within the valid range [{self.min_value}, {self.max_value}]")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--control'):
            arg_name = arg.replace('--control', '').lstrip('-').replace('-', '_')
            control_args[arg_name] = True
        elif arg.startswith('--nested'):
            arg_name = arg.replace('--nested', '').lstrip('-').replace('-', '_')
            nested_args[arg_name] = arg.split('=')[1] if '=' in arg else True
        elif arg.startswith('--custom'):
            arg_name = arg.replace('--custom', '').lstrip('-').replace('-', '_')
            custom_args[arg_name] = arg.split('=')[1] if '=' in arg else True

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is None:
            return vars_dict

        for var in extra_vars:
            key, value = list(var.items())[0]
            if key in vars_dict:
                if isinstance(vars_dict[key], dict) and isinstance(value, dict):
                    MergeHelper.merge_extra_vars(vars_dict[key], value)
                else:
                    vars_dict[key] = value
            else:
                vars_dict[key] = value

        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        try:
            # Check if the key corresponds to an integer argument
            if parser_name in ['main', 'virsh'] and key in ['port', 'pid', 'id']:
                values_dict[key] = int(value)
            # Check if the key corresponds to a boolean argument
            elif parser_name == 'main' and key in ['debug', 'verbose']:
                values_dict[key] = value.lower() in ['true', '1', 't', 'y', 'yes']
            # Check if the key corresponds to a list argument
            elif parser_name == 'main' and key == 'tags':
                values_dict[key] = value.split(',')
        except (ValueError, AttributeError):
            # If conversion fails, keep the original value
            continue

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    plugin_spec_path = os.path.join(plugin_dir, 'spec.json')
    with open(plugin_spec_path, 'r') as f:
        spec = json.load(f)

    flat_dict = {}
    def flatten(x, name=''):
        if type(x) is dict:
            for a in x:
                flatten(x[a], name + a + '_')
        elif type(x) is list:
            i = 0
            for a in x:
                flatten(a, name + str(i) + '_')
                i += 1
        else:
            flat_dict[name[:-1]] = x

    flatten(spec)
    return flat_dict

